def removeSublistRepeatedly(nums, pattern):
    m = len(pattern)
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and pattern[i] != pattern[k]:
            k = fail[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        fail[i] = k
    vals = []
    states = []
    for x in nums:
        k = states[-1] if states else 0
        while k and x != pattern[k]:
            k = fail[k - 1]
        if x == pattern[k]:
            k += 1
        vals.append(x)
        states.append(k)
        if k == m:
            del vals[-m:]
            del states[-m:]
    return vals
